```js
const cv = document.getElementById("cv");
const ctx = cv.getContext("2d");        // 获取 2D 绘图上下文

// 矩形
ctx.fillStyle = "#a63d2a";
ctx.fillRect(10, 10, 100, 60);

// 路径与线条
